{"content":"import test from 'node:test';
import assert from 'node:assert/strict';
import { toRoman } from '../src/roman.js';

test('converts boundaries, base symbols, subtractive pairs, and mixed values', () => {
  const cases = [
    [1, 'I'],
    [2, 'II'],
    [3, 'III'],
    [4, 'IV'],
    [5, 'V'],
    [8, 'VIII'],
    [9, 'IX'],
    [10, 'X'],
    [40, 'XL'],
    [50, 'L'],
    [90, 'XC'],
    [100, 'C'],
    [400, 'CD'],
    [500, 'D'],
    [900, 'CM'],
    [1000, 'M'],
    [49, 'XLIX'],
    [944, 'CMXLIV'],
    [1984, 'MCMLXXXIV'],
    [2024, 'MMXXIV'],
    [3888, 'MMMDCCCLXXXVIII'],
    [3999, 'MMMCMXCIX'],
  ];
  for (const [input, expected] of cases) {
    assert.equal(toRoman(input), expected, `input: ${input}`);
  }
});

test('rejects out-of-range numbers, non-integers, and non-number inputs', () => {
  const invalid = [
    -100, -1, -0, 0, 4000, 10000, Number.MAX_SAFE_INTEGER,
    0.5, 1.5, 3998.5, NaN, Infinity, -Infinity,
    '1', '', null, undefined, true, false, {}, [], [1], 1n, Symbol('1'),
  ];
  for (const input of invalid) {
    assert.throws(() => toRoman(input), RangeError, `input: ${String(input)}`);
  }
});

test('every supported integer has a unique canonical numeral with the correct value', () => {
  const canonical = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
  const values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  const seen = new Set();

  for (let n = 1; n <= 3999; n++) {
    const roman = toRoman(n);
    assert.notEqual(roman, '');
    assert.match(roman, canonical);
    assert.ok(!seen.has(roman), `duplicate numeral: ${roman}`);
    seen.add(roman);

    let decoded = 0;
    for (let i = 0; i < roman.length; i++) {
      const current = values[roman[i]];
      const next = values[roman[i + 1]] ?? 0;
      decoded += current < next ? -current : current;
    }
    assert.equal(decoded, n, `numeral: ${roman}`);
  }
});
